content:
:root {
  --primary: #2563eb;
  --primary-hover: #1d4ed8;
  --primary-light: #eff6ff;
  --bg-main: #f8fafc;
  --card-bg: #ffffff;
  --border-color: #e2e8f0;
  --border-hover: #cbd5e1;
  --text-main: #0f172a;
  --text-muted: #64748b;
  --shadow-sm: 0 1px 2px 0 rgba(0, 0, 0, 0.05);
  --shadow-md: 0 4px 6px -1px rgba(0, 0, 0, 0.07), 0 2px 4px -2px rgba(0, 0, 0, 0.05);
  --shadow-lg: 0 10px 15px -3px rgba(0, 0, 0, 0.08), 0 4px 6px -4px rgba(0, 0, 0, 0.05);
  --radius-sm: 6px;
  --radius-md: 10px;
  --radius-lg: 16px;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif;
  background-color: var(--bg-main);
  color: var(--text-main);
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
}

input,
select,
button {
  font-family: inherit;
  font-size: inherit;
}

/* アプリ全体レイアウト */
.app-wrapper {
  min-height: 100vh;
  padding: 24px 16px 48px;
  background-color: var(--bg-main);
}

.app-container {
  max-width: 1000px;
  margin: 0 auto;
}

/* ヘッダー */
.app-header {
  text-align: center;
  margin-bottom: 24px;
}

.header-title {
  font-size: 1.75rem;
  font-weight: 800;
  color: var(--text-main);
  letter-spacing: -0.02em;
}

.header-subtitle {
  font-size: 0.95rem;
  color: var(--text-muted);
  max-width: 640px;
  margin: 0 auto;
}

/* プリセットセクション */
.preset-section {
  background-color: #ffffff;
  border: 1px solid var(--border-color);
  border-radius: var(--radius-md);
  padding: 16px 20px;
  margin-bottom: 24px;
  box-shadow: var(--shadow-sm);
}

.preset-title {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 0.85rem;
  font-weight: 700;
  color: #4f46e5;
  margin-bottom: 12px;
}

.preset-chips {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

.preset-chip {
  background-color: #f1f5f9;
  border: 1px solid #e2e8f0;
  border-radius: 9999px;
  padding: 6px 14px;
  font-size: 0.82rem;
  font-weight: 500;
  color: #334155;
  cursor: pointer;
  transition: all 0.15s ease-in-out;
}

.preset-chip:hover {
  background-color: #e2e8f0;
  border-color: #cbd5e1;
  color: #0f172a;
}

/* メイン変換エリア */
.converter-main {
  display: flex;
  flex-direction: column;
  gap: 20px;
}

/* ヒーロー入力セクション */
.input-hero {
  background-color: #ffffff;
  border: 2px solid #3b82f6;
  border-radius: var(--radius-lg);
  padding: 24px;
  box-shadow: var(--shadow-md);
}

.hero-label {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 0.9rem;
  font-weight: 700;
  color: #1e3a8a;
  margin-bottom: 12px;
}

.hero-input-row {
  display: flex;
  gap: 12px;
  align-items: stretch;
}

.hero-input {
  flex: 1;
  min-width: 0;
  padding: 12px 16px;
  font-size: 1.5rem;
  font-weight: 700;
  color: var(--text-main);
  background-color: #f8fafc;
  border: 1px solid var(--border-color);
  border-radius: var(--radius-md);
  outline: none;
  transition: border-color 0.15s, box-shadow 0.15s;
}

.hero-input:focus {
  border-color: var(--primary);
  box-shadow: 0 0 0 3px rgba(37, 99, 235, 0.15);
  background-color: #ffffff;
}

.hero-unit-select {
  padding: 0 16px;
  font-size: 1rem;
  font-weight: 600;
  color: #1e293b;
  background-color: #f8fafc;
  border: 1px solid var(--border-color);
  border-radius: var(--radius-md);
  cursor: pointer;
  outline: none;
  transition: border-color 0.15s;
}

.hero-unit-select:focus {
  border-color: var(--primary);
  box-shadow: 0 0 0 3px rgba(37, 99, 235, 0.15);
}

.hero-clear-btn {
  display: flex;
  align-items: center;
  gap: 4px;
  padding: 0 16px;
  font-size: 0.85rem;
  font-weight: 600;
  color: #64748b;
  background-color: #f1f5f9;
  border: 1px solid var(--border-color);
  border-radius: var(--radius-md);
  cursor: pointer;
  transition: background-color 0.15s, color 0.15s;
  white-space: nowrap;
}

.hero-clear-btn:hover {
  background-color: #fee2e2;
  color: #dc2626;
  border-color: #fca5a5;
}

/* 微調整ボタンバー */
.quick-adjust-row {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 8px;
  margin-top: 16px;
  padding-top: 14px;
  border-top: 1px dashed var(--border-color);
}

.adjust-btn {
  background-color: #f8fafc;
  border: 1px solid var(--border-color);
  border-radius: var(--radius-sm);
  padding: 4px 10px;
  font-size: 0.8rem;
  font-weight: 600;
  color: #475569;
  cursor: pointer;
  transition: all 0.15s;
}

.adjust-btn:hover {
  background-color: #e2e8f0;
  border-color: #cbd5e1;
  color: #0f172a;
}

/* タブバー */
.tabs-container {
  display: flex;
  gap: 8px;
  border-bottom: 2px solid var(--border-color);
  padding-bottom: 4px;
}

.tab-btn {
  background: none;
  border: none;
  padding: 8px 16px;
  font-size: 0.9rem;
  font-weight: 600;
  color: var(--text-muted);
  cursor: pointer;
  border-radius: var(--radius-sm);
  transition: color 0.15s, background-color 0.15s;
}

.tab-btn:hover {
  color: var(--text-main);
  background-color: #f1f5f9;
}

.tab-btn-active {
  color: var(--primary);
  background-color: var(--primary-light);
}

/* 換算カードグリッド */
.units-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
  gap: 16px;
}

/* 単位カード */
.unit-card {
  background-color: var(--card-bg);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-md);
  padding: 16px;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  box-shadow: var(--shadow-sm);
  transition: transform 0.15s ease, box-shadow 0.15s ease, border-color 0.15s ease;
  cursor: pointer;
}

.unit-card:hover {
  border-color: var(--border-hover);
  box-shadow: var(--shadow-md);
}

.unit-card-active {
  border: 2px solid var(--primary);
  background-color: #fbfdff;
  box-shadow: 0 0 0 1px var(--primary), var(--shadow-md);
}

.unit-card-header {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  margin-bottom: 12px;
}

.unit-name {
  font-size: 1rem;
  font-weight: 700;
  color: var(--text-main);
}

.unit-symbol {
  font-size: 0.85rem;
  color: var(--text-muted);
  margin-left: 4px;
}

.unit-system-badge {
  font-size: 0.7rem;
  font-weight: 600;
  padding: 2px 8px;
  border-radius: 9999px;
  text-transform: uppercase;
}

.metric-badge {
  background-color: #dcfce7;
  color: #15803d;
}

.imperial-badge {
  background-color: #fef3c7;
  color: #b45309;
}

.unit-card-body {
  margin-bottom: 14px;
}

.unit-value-display {
  display: flex;
  align-items: center;
  gap: 8px;
  background-color: #f8fafc;
  border: 1px solid var(--border-color);
  border-radius: var(--radius-sm);
  padding: 6px 12px;
}

.unit-input-field {
  flex: 1;
  min-width: 0;
  background: transparent;
  border: none;
  font-size: 1.25rem;
  font-weight: 700;
  color: var(--text-main);
  outline: none;
}

.unit-card-footer {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding-top: 10px;
  border-top: 1px solid #f1f5f9;
}

.copy-btn {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  background-color: #f8fafc;
  border: 1px solid var(--border-color);
  border-radius: var(--radius-sm);
  padding: 4px 10px;
  font-size: 0.75rem;
  font-weight: 600;
  color: #475569;
  cursor: pointer;
  transition: all 0.15s;
}

.copy-btn:hover {
  background-color: #f1f5f9;
  border-color: #cbd5e1;
  color: #0f172a;
}

.copy-btn-copied {
  background-color: #dcfce7;
  border-color: #86efac;
  color: #15803d;
}

/* 視覚的スケール比較セクション */
.scale-section {
  background-color: #ffffff;
  border: 1px solid var(--border-color);
  border-radius: var(--radius-lg);
  padding: 20px;
  box-shadow: var(--shadow-sm);
}

.scale-title {
  font-size: 0.95rem;
  font-weight: 700;
  color: #334155;
  margin-bottom: 16px;
}

.scale-bars-container {
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.scale-bar-item {
  display: grid;
  grid-template-columns: 140px 1fr 140px;
  align-items: center;
  gap: 12px;
}

.scale-bar-label {
  font-size: 0.8rem;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.scale-bar-track {
  background-color: #e2e8f0;
  border-radius: 9999px;
  height: 10px;
  overflow: hidden;
}

.scale-bar-fill {
  height: 100%;
  border-radius: 9999px;
  transition: width 0.3s ease, background-color 0.2s ease;
}

.scale-bar-val {
  font-size: 0.8rem;
  font-weight: 600;
  color: #64748b;
  text-align: right;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

/* トースト通知 */
.copy-toast {
  position: fixed;
  bottom: 24px;
  left: 50%;
  transform: translateX(-50%);
  background-color: #0f172a;
  color: #f8fafc;
  padding: 10px 20px;
  border-radius: 9999px;
  font-size: 0.85rem;
  font-weight: 600;
  box-shadow: var(--shadow-lg);
  z-index: 1000;
  animation: toastFadeIn 0.2s ease-out;
}

@keyframes toastFadeIn {
  from {
    opacity: 0;
    transform: translate(-50%, 12px);
  }
  to {
    opacity: 1;
    transform: translate(-50%, 0);
  }
}

/* レスポンシブ対応 */
@media (max-width: 640px) {
  .app-wrapper {
    padding: 16px 12px 36px;
  }

  .header-title {
    font-size: 1.35rem;
  }

  .hero-input-row {
    flex-direction: column;
  }

  .hero-input {
    font-size: 1.25rem;
  }

  .hero-unit-select,
  .hero-clear-btn {
    padding: 10px 14px;
  }

  .units-grid {
    grid-template-columns: 1fr;
  }

  .scale-bar-item {
    grid-template-columns: 90px 1fr 90px;
    gap: 8px;
  }

  .scale-bar-label,
  .scale-bar-val {
    font-size: 0.72rem;
  }
}

export type UnitKey = 'mm' | 'cm' | 'm' | 'km' | 'inch' | 'foot' | 'yard' | 'mile';

export type FilterTab = 'all' | 'metric' | 'imperial';

export interface UnitInfo {
  key: UnitKey;
  name: string;
  symbol: string;
  toMeters: number;
  system: 'metric' | 'imperial';
  description: string;
}

export interface ConversionResult {
  unit: UnitInfo;
  value: number;
  formattedValue: string;
}

export interface PresetItem {
  label: string;
  value: number;
  unitKey: UnitKey;
  description: string;
}

export interface ConversionCardProps {
  unitInfo: UnitInfo;
  value: number;
  isBase: boolean;
  onSelectAsBase?: (key: UnitKey) => void;
  onValueChange?: (val: number) => void;
  onCopy?: (text: string) => void;
}

export interface ScaleBarProps {
  results: readonly ConversionResult[];
  baseUnitKey: UnitKey;
}

