export const roundTo = (val: number, decimals: number): number => {
  const factor = Math.pow(10, decimals);
  return Math.round(val * factor) / factor;
};

export const convertLength = (value: number, fromUnit: UnitKey, toUnit: UnitKey): number => {
  if (isNaN(value)) {
    return 0;
  }
  if (fromUnit === toUnit) {
    return value;
  }
  const fromMetersRate = SUPPORTED_UNITS[fromUnit].toMeters;
  const toMetersRate = SUPPORTED_UNITS[toUnit].toMeters;
  const meters = value * fromMetersRate;
  return meters / toMetersRate;
};

export const formatLengthNumber = (value: number): string => {
  if (isNaN(value)) {
    return '0';
  }
  if (value === 0) {
    return '0';
  }

  const abs = Math.abs(value);

  if (abs >= 1e9 || (abs < 1e-5 && abs > 0)) {
    const expStr = value.toExponential(4);
    const [mantissa, exponent] = expStr.split('e');
    const trimmedMantissa = parseFloat(mantissa).toString();
    return `${trimmedMantissa}e${exponent}`;
  }

  let formatted: string;
  if (abs >= 1000) {
    formatted = value.toLocaleString('ja-JP', {
      maximumFractionDigits: 3,
      minimumFractionDigits: 0,
    });
  } else if (abs >= 10) {
    formatted = roundTo(value, 4).toLocaleString('ja-JP', {
      maximumFractionDigits: 4,
    });
  } else if (abs >= 1) {
    formatted = roundTo(value, 5).toLocaleString('ja-JP', {
      maximumFractionDigits: 5,
    });
  } else {
    formatted = roundTo(value, 6).toLocaleString('ja-JP', {
      maximumFractionDigits: 6,
    });
  }

  return formatted;
};

export const calculateAllUnits = (value: number, baseUnitKey: UnitKey): ConversionResult[] => {
  const safeValue = isNaN(value) ? 0 : value;

  return UNIT_LIST.map((unit) => {
    const converted = convertLength(safeValue, baseUnitKey, unit.key);
    return {
      unit,
      value: converted,
      formattedValue: formatLengthNumber(converted),
    };
  });
};

import { useState, useEffect, ChangeEvent, KeyboardEvent } from 'react';
import { Copy, Check, Star } from 'lucide-react';
import { ConversionCardProps } from '../types';
import { formatLengthNumber } from '../utils/converter';

const copyToClipboardFallback = (text: string): boolean => {
  try {
    const textArea = document.createElement('textarea');
    textArea.value = text;
    textArea.style.position = 'fixed';
    textArea.style.left = '-999999px';
    textArea.style.top = '-999999px';
    document.body.appendChild(textArea);
    textArea.focus();
    textArea.select();
    const successful = document.execCommand('copy');
    document.body.removeChild(textArea);
    return successful;
  } catch {
    return false;
  }
};

const ConversionCard = ({
  unitInfo,
  value,
  isBase,
  onSelectAsBase,
  onValueChange,
  onCopy,
}: ConversionCardProps) => {
  const [localInput, setLocalInput] = useState<string>('');
  const [isCopied, setIsCopied] = useState<boolean>(false);
  const [isFocused, setIsFocused] = useState<boolean>(false);

  useEffect(() => {
    if (!isFocused) {
      setLocalInput(formatLengthNumber(value));
    }
  }, [value, isFocused]);

  const handleInputChange = (e: ChangeEvent<HTMLInputElement>) => {
    const valStr = e.target.value;
    setLocalInput(valStr);

    const parsed = parseFloat(valStr);
    if (!isNaN(parsed) && parsed >= 0) {
      if (!isBase) {
        onSelectAsBase?.(unitInfo.key);
      }
      onValueChange?.(parsed);
    } else if (valStr === '') {
      onValueChange?.(0);
    }
  };

  const handleInputBlur = () => {
    setIsFocused(false);
    setLocalInput(formatLengthNumber(value));
  };

  const handleInputFocus = () => {
    setIsFocused(true);
  };

  const handleCopy = () => {
    const formatted = formatLengthNumber(value);
    const textToCopy = `${formatted} ${unitInfo.symbol}`;

    const triggerSuccess = () => {
      onCopy?.(textToCopy);
      setIsCopied(true);
      setTimeout(() => {
        setIsCopied(false);
      }, 1800);
    };

    if (navigator.clipboard && window.isSecureContext) {
      navigator.clipboard
        .writeText(textToCopy)
        .then(triggerSuccess)
        .catch(() => {
          if (copyToClipboardFallback(textToCopy)) {
            triggerSuccess();
          }
        });
    } else {
      if (copyToClipboardFallback(textToCopy)) {
        triggerSuccess();
      }
    }
  };

  const handleCardClick = () => {
    if (!isBase) {
      onSelectAsBase?.(unitInfo.key);
    }
  };

  const handleCardKeyDown = (e: KeyboardEvent<HTMLDivElement>) => {
    if (e.key === 'Enter' || e.key === ' ') {
      e.preventDefault();
      handleCardClick();
    }
  };

  const badgeClass =
    unitInfo.system === 'metric'
      ? 'unit-system-badge metric-badge'
      : 'unit-system-badge imperial-badge';

  const badgeText = unitInfo.system === 'metric' ? 'メートル法' : 'ヤード・ポンド法';

  return (
    <div
      role="button"
      tabIndex={0}
      className={`unit-card ${isBase ? 'unit-card-active' : ''}`}
      onClick={handleCardClick}
      onKeyDown={handleCardKeyDown}
      aria-label={`${unitInfo.name}を基準単位として選択`}
    >
      <div className="unit-card-header">
        <div>
          <span className="unit-name">{unitInfo.name}</span>
          <span className="unit-symbol">({unitInfo.symbol})</span>
        </div>
        <div style={{ display: 'flex', alignItems: 'center', gap: '8px' }}>
          <span className={badgeClass}>{badgeText}</span>
          {isBase && (
            <span
              style={{
                display: 'inline-flex',
                alignItems: 'center',
                gap: '2px',
                fontSize: '0.75rem',
                fontWeight: 600,
                color: '#2563eb',
              }}
            >
              <Star size={14} fill="#2563eb" /> 基準
            </span>
          )}
        </div>
      </div>

      <div className="unit-card-body">
        <div className="unit-value-display">
          <input
            type="text"
            className="unit-input-field"
            value={localInput}
            onChange={handleInputChange}
            onFocus={handleInputFocus}
            onBlur={handleInputBlur}
            onClick={(e) => e.stopPropagation()}
            aria-label={`${unitInfo.name}の値入力`}
            placeholder="0"
          />
          <span style={{ fontSize: '1.1rem', fontWeight: 600, color: '#64748b' }}>
            {unitInfo.symbol}
          </span>
        </div>
        <p
          style={{
            fontSize: '0.8rem',
            color: '#64748b',
            margin: '6px 0 0 0',
            lineHeight: 1.4,
          }}
        >
          {unitInfo.description}
        </p>
      </div>

      <div className="unit-card-footer">
        <button
          type="button"
          className={`copy-btn ${isCopied ? 'copy-btn-copied' : ''}`}
          onClick={(e) => {
            e.stopPropagation();
            handleCopy();
          }}
          title={`${unitInfo.name}の値をコピー`}
        >
          {isCopied ? (
            <>
              <Check size={14} /> コピー完了
            </>
          ) : (
            <>
              <Copy size={14} /> コピー
            </>
          )}
        </button>

        {!isBase && (
          <button
            type="button"
            className="adjust-btn"
            style={{ padding: '4px 10px', fontSize: '0.75rem' }}
            onClick={(e) => {
              e.stopPropagation();
              onSelectAsBase?.(unitInfo.key);
            }}
          >
            基準にする
          </button>
        )}
      </div>
    </div>
  );
};

export default ConversionCard;

import { ScaleBarProps } from '../types';

const VisualComparison = ({ results = [], baseUnitKey }: ScaleBarProps) => {
  // 対数スケールを用いて換算された各単位の「数値の大きさ」を視覚的に比較
  const safeResults = results.filter((res) => !isNaN(res.value) && res.value > 0);

  // 10を底とする対数を取って相対バーの幅を算出
  const logValues = safeResults.map((r) => Math.log10(r.value));
  const minLog = logValues.length > 0 ? Math.min(...logValues) : 0;
  const maxLog = logValues.length > 0 ? Math.max(...logValues) : 1;
  const rawDiff = maxLog - minLog;
  const logRange = rawDiff > 0.0001 ? rawDiff : 1;

  const calculateBarWidth = (value: number): number => {
    if (value <= 0 || isNaN(value)) {
      return 2;
    }
    if (rawDiff <= 0.0001) {
      return 50;
    }
    const logVal = Math.log10(value);
    const normalized = (logVal - minLog) / logRange;
    // 最小5%、最大100%の範囲にマッピング
    return Math.max(5, Math.min(100, Math.round(normalized * 95 + 5)));
  };

  return (
    <div className="scale-section">
      <h3 className="scale-title">各単位での換算数値スケール比較（対数表示）</h3>
      <p style={{ fontSize: '0.8rem', color: '#64748b', margin: '0 0 16px 0', lineHeight: 1.5 }}>
        ※ 同一の長さを各単位で表した際の「数値そのものの桁数・大きさ」を対数スケール（log10）で比較表示しています。
      </p>
      <div className="scale-bars-container">
        {results.map((item) => {
          const isBase = item.unit.key === baseUnitKey;
          const barWidth = calculateBarWidth(item.value);

          return (
            <div key={item.unit.key} className="scale-bar-item">
              <span
                className="scale-bar-label"
                style={{
                  fontWeight: isBase ? 700 : 500,
                  color: isBase ? '#2563eb' : '#334155',
                }}
              >
                {item.unit.name} ({item.unit.symbol})
              </span>
              <div
                className="scale-bar-track"
                role="progressbar"
                aria-valuenow={barWidth}
                aria-valuemin={0}
                aria-valuemax={100}
                aria-label={`${item.unit.name}の数値スケール: ${barWidth}% (${item.formattedValue} ${item.unit.symbol})`}
              >
                <div
                  className="scale-bar-fill"
                  style={{
                    width: `${barWidth}%`,
                    backgroundColor: isBase ? '#2563eb' : '#94a3b8',
                  }}
                />
              </div>
              <span className="scale-bar-val">
                {item.formattedValue} {item.unit.symbol}
              </span>
            </div>
          );
        })}
      </div>
    </div>
  );
};

export default VisualComparison;

import { useState, useMemo, useRef, useEffect } from 'react';
import { ArrowLeftRight, X, Sparkles, SlidersHorizontal } from 'lucide-react';
import { UnitKey, FilterTab, PresetItem } from './types';
import {
  SUPPORTED_UNITS,
  UNIT_LIST,
  PRESETS,
  calculateAllUnits,
} from './utils/converter';
import ConversionCard from './components/ConversionCard';
import VisualComparison from './components/VisualComparison';
import './index.css';

const App = () => {
  const [baseValue, setBaseValue] = useState<number>(1);
  const [baseUnit, setBaseUnit] = useState<UnitKey>('m');
  const [activeTab, setActiveTab] = useState<FilterTab>('all');
  const [toastMessage, setToastMessage] = useState<string | null>(null);
  const toastTimeoutRef = useRef<number | null>(null);

  // コンポーネントアンマウント時にタイマーをクリア
  useEffect(() => {
    return () => {
      if (toastTimeoutRef.current !== null) {
        window.clearTimeout(toastTimeoutRef.current);
      }
    };
  }, []);

  // 全単位の換算結果を計算
  const conversionResults = useMemo(() => {
    return calculateAllUnits(baseValue, baseUnit);
  }, [baseValue, baseUnit]);

  // フィルタリングされた単位一覧
  const filteredResults = useMemo(() => {
    if (activeTab === 'metric') {
      return conversionResults.filter((r) => r.unit.system === 'metric');
    }
    if (activeTab === 'imperial') {
      return conversionResults.filter((r) => r.unit.system === 'imperial');
    }
    return conversionResults;
  }, [conversionResults, activeTab]);

  // トースト表示処理（タイマーの二重発火を防止）
  const showToast = (message: string) => {
    if (toastTimeoutRef.current !== null) {
      window.clearTimeout(toastTimeoutRef.current);
    }
    setToastMessage(message);
    toastTimeoutRef.current = window.setTimeout(() => {
      setToastMessage(null);
      toastTimeoutRef.current = null;
    }, 2200);
  };

  // メイン入力の変更処理
  const handleMainInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const val = parseFloat(e.target.value);
    if (!isNaN(val) && val >= 0) {
      setBaseValue(val);
    } else if (e.target.value === '') {
      setBaseValue(0);
    }
  };

  // 微調整アクション（0の場合は基準値1として乗算）
  const handleAdjust = (multiplier: number) => {
    const currentVal = baseValue === 0 ? 1 : baseValue;
    const newVal = Math.round(currentVal * multiplier * 100000) / 100000;
    setBaseValue(Math.max(0, newVal));
  };

  // 微調整アクション（加減算）
  const handleStep = (step: number) => {
    const newVal = Math.round((baseValue + step) * 100000) / 100000;
    setBaseValue(Math.max(0, newVal));
  };

  // プリセット適用
  const handleApplyPreset = (preset: PresetItem) => {
    setBaseUnit(preset.unitKey);
    setBaseValue(preset.value);
    showToast(`プリセット「${preset.label}」を適用しました`);
  };

  // クリア処理
  const handleClear = () => {
    setBaseValue(0);
  };

  // カードからの基準単位選択
  const handleSelectAsBase = (key: UnitKey) => {
    setBaseUnit(key);
  };

  // カードからの数値編集
  const handleCardValueChange = (val: number) => {
    setBaseValue(val);
  };

  return (
    <div className="app-wrapper">
      <div className="app-container">
        {/* ヘッダー */}
        <header className="app-header">
          <div style={{ display: 'inline-flex', alignItems: 'center', gap: '8px', marginBottom: '8px' }}>
            <ArrowLeftRight size={28} color="#2563eb" />
            <h1 className="header-title">長さ・距離 相互変換ツール</h1>
          </div>
          <p className="header-subtitle">
            ミリ・センチ・メートル・キロ・インチ・フィート・ヤード・マイルを即座に一括計算。直感的なスケール比較と便利なプリセットつき。
          </p>
        </header>

        {/* プリセットセクション */}
        <section className="preset-section">
          <div className="preset-title">
            <Sparkles size={16} color="#4f46e5" /> 身近な長さプリセットですぐに試す
          </div>
          <div className="preset-chips">
            {PRESETS.map((p) => (
              <button
                key={p.label}
                type="button"
                className="preset-chip"
                onClick={() => handleApplyPreset(p)}
                title={p.description}
              >
                {p.label} ({p.value} {SUPPORTED_UNITS[p.unitKey].symbol})
              </button>
            ))}
          </div>
        </section>

        {/* メイン変換エリア */}
        <main className="converter-main">
          {/* ヒーロー入力フィールド */}
          <div className="input-hero">
            <label className="hero-label" htmlFor="hero-base-input">
              <SlidersHorizontal size={16} /> 変換元の数値と基準単位を入力
            </label>
            <div className="hero-input-row">
              <input
                id="hero-base-input"
                type="number"
                min="0"
                step="any"
                className="hero-input"
                value={baseValue === 0 ? '' : baseValue}
                onChange={handleMainInputChange}
                placeholder="数値を入力..."
                aria-label="基準となる数値"
              />
              <select
                className="hero-unit-select"
                value={baseUnit}
                onChange={(e) => setBaseUnit(e.target.value as UnitKey)}
                aria-label="基準単位の選択"
              >
                <optgroup label="メートル法 (SI)">
                  <option value="mm">ミリメートル (mm)</option>
                  <option value="cm">センチメートル (cm)</option>
                  <option value="m">メートル (m)</option>
                  <option value="km">キロメートル (km)</option>
                </optgroup>
                <optgroup label="ヤード・ポンド法">
                  <option value="inch">インチ (in)</option>
                  <option value="foot">フィート (ft)</option>
                  <option value="yard">ヤード (yd)</option>
                  <option value="mile">マイル (mi)</option>
                </optgroup>
              </select>
              <button
                type="button"
                className="hero-clear-btn"
                onClick={handleClear}
                title="数値を0にリセット"
                aria-label="数値をリセット"
              >
                <X size={18} /> リセット
              </button>
            </div>

            {/* クイック微調整ボタン */}
            <div className="quick-adjust-row">
              <span style={{ fontSize: '0.8rem', color: '#64748b', marginRight: '4px' }}>
                すばやく倍率調整:
              </span>
              <button
                type="button"
                className="adjust-btn"
                onClick={() => handleStep(-1)}
              >
                -1
              </button>
              <button
                type="button"
                className="adjust-btn"
                onClick={() => handleStep(1)}
              >
                +1
              </button>
              <button
                type="button"
                className="adjust-btn"
                onClick={() => handleAdjust(0.1)}
              >
                ÷ 10
              </button>
              <button
                type="button"
                className="adjust-btn"
                onClick={() => handleAdjust(0.5)}
              >
                ÷ 2
              </button>
              <button
                type="button"
                className="adjust-btn"
                onClick={() => handleAdjust(2)}
              >
                × 2
              </button>
              <button
                type="button"
                className="adjust-btn"
                onClick={() => handleAdjust(10)}
              >
                × 10
              </button>
              <button
                type="button"
                className="adjust-btn"
                onClick={() => handleAdjust(1.1)}
              >
                +10%
              </button>
              <button
                type="button"
                className="adjust-btn"
                onClick={() => handleAdjust(0.9)}
              >
                -10%
              </button>
            </div>
          </div>

          {/* 表示切り替えタブ */}
          <div className="tabs-container">
            <button
              type="button"
              className={`tab-btn ${activeTab === 'all' ? 'tab-btn-active' : ''}`}
              onClick={() => setActiveTab('all')}
            >
              すべての単位 ({UNIT_LIST.length})
            </button>
            <button
              type="button"
              className={`tab-btn ${activeTab === 'metric' ? 'tab-btn-active' : ''}`}
              onClick={() => setActiveTab('metric')}
            >
              メートル法のみ
            </button>
            <button
              type="button"
              className={`tab-btn ${activeTab === 'imperial' ? 'tab-btn-active' : ''}`}
              onClick={() => setActiveTab('imperial')}
            >
              ヤード・ポンド法のみ
            </button>
          </div>

          {/* 換算カードグリッド */}
          <div className="units-grid">
            {filteredResults.map((result) => (
              <ConversionCard
                key={result.unit.key}
                unitInfo={result.unit}
                value={result.value}
                isBase={result.unit.key === baseUnit}
                onSelectAsBase={handleSelectAsBase}
                onValueChange={handleCardValueChange}
                onCopy={(text) => showToast(`「${text}」をコピーしました`)}
              />
            ))}
          </div>

          {/* 視覚的スケール比較 */}
          <VisualComparison
            results={conversionResults}
            baseUnitKey={baseUnit}
          />
        </main>

        {/* コピートースト通知 */}
        {toastMessage && <div className="copy-toast">{toastMessage}</div>}
      </div>
    </div>
  );
};

export default App;
